    {
      "policy_source_id": "q13",
      "interpretation": "The agent must ensure that cancellation rules are met before calling the API (e.g., no portion of the flight has already been flown, or the user has travel insurance for health-related cancellation).",
      "modality": "REQUIRE"
    },
    {
      "policy_source_id": "q13",
      "interpretation": "The agent must not make tool calls without first confirming the user's intent or without ensuring compliance with policy rules.",
      "modality": "FORBID"
    }
